script:
fleet_event = {
	id = namarian.2
	hide_window = yes

	is_triggered_only = yes

	trigger = {
		owner = { is_country_type = nomad }
		NOT = { has_fleet_flag = nomad_on_mission }
	}

	immediate = {
		clear_fleet_actions = this
		if = {
			limit = {
				owner = {
					NOT = { has_country_flag = nomad_mid_point_reached }
				}
			}
			queue_actions = {
				find_random_system = {
					trigger = {
						id = namarian.2.trigger.1
						has_star_flag = nomad_mid_point
					}
					found_system = {
						move_to = this
					}
				}
			}
		}
		else = {
			queue_actions = {
				find_random_system = {
					trigger = {
						id = namarian.2.trigger.2
						has_star_flag = nomad_end_point
					}
					found_system = {
						move_to = this
					}
				}
			}
		}
	}
}

