country_event = {
	id = namarian.530
	title = namarian.500.title
	desc = {
		text = namarian.530.desc.15ships
		trigger = {
			NOT = { has_country_flag = double_fleet }
		}
	}
	desc = {
		text = namarian.530.desc.30ships
		trigger = {
			has_country_flag = double_fleet
		}
	}
	picture = GFX_evt_unknown_ships
	show_sound = event_ship_thrusters
	location = root.capital_scope

	is_triggered_only = yes

	trigger = {
		NOT = { has_country_flag = nomad_ignores }
	}

	immediate = {
		event_target:nomad01_country = {
			set_country_flag = nomad_ships_sold
			random_controlled_ship = {
				limit = {
					fleet = {
						has_fleet_flag = nomad_fleet
					}
				}
				fleet = {
					save_event_target_as = nomad_fleet
				}
			}
		}

		create_fleet = {
			name = "NAME_Nomad_Delivery"
			effect = {
				set_owner = root
				create_ship_design = {
					design = "NAME_Nomad_Cruiser"
				}
				while = {
					count = 5
					create_ship = {
						design = last_created_design
						upgradable = no
					}
				}
				set_location = {
					target = root.capital_scope
					distance = 5
					angle = random
				}
			}
		}

		if = {
			limit = {
				has_country_flag = double_fleet
			}
			create_fleet = {
				name = "NAME_Redirected_Nomad_Delivery"
				effect = {
					set_owner = root
					create_ship_design = {
						design = "NAME_Nomad_Cruiser"
					}
					while = {
						count = 10
						create_ship = {
							design = last_created_design
							upgradable = no
						}
					}
					set_location = {
						target = root.capital_scope
						distance = 15
						angle = random
					}
				}
			}
		}
	}

	option = {
		name = OK
		hidden_effect = {
			event_target:nomad_fleet = {
				remove_fleet_flag = nomad_on_mission
				fleet_event = { id = namarian.2 }
			}
		}
	}
}
